import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SequenceHighlightProps = Record<string, any>;

const SequenceHighlight: React.FC<SequenceHighlightProps> = ({
  backgroundColor = "#0e0e1a",
  transparentBackground = false,
  durationInSeconds = 12,
  inactiveCardColor = "#31215b",
  activeGradientStart = "#9c46ff",
  activeGradientEnd = "#50179e",
  inactiveTextColor = "#7e749c",
  activeTextColor = "#ffffff",
  pointFontSize = 23,
  messageFontSize = 46,
  items = [
    { number: "1", message: "Initialize core systems and verify parameters" },
    { number: "2", message: "Establish secure connection protocols" },
    { number: "3", message: "Synchronize database clusters" },
    { number: "4", message: "Deploy primary processing units" },
    { number: "5", message: "Execute integrity checks" },
    { number: "6", message: "Finalize launch sequence" },
  ],
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Ensure we only use up to 6 items as requested
  const displayItems = items.slice(0, 6);
  
  // Timing calculations
  const totalFrames = durationInSeconds * fps;
  const introDuration = 45; // Frames for initial grid appearance
  const outroDuration = 30;
  const cycleFrames = totalFrames - introDuration - outroDuration;
  const framesPerItem = cycleFrames / Math.max(1, displayItems.length);

  // Layout calculations
  const cardSize = width * 0.11;
  const gapX = cardSize * 0.2;
  const gapY = cardSize * 0.2;
  const borderRadius = cardSize * 0.15;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Montserrat, sans-serif",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {/* Grid Container */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: `${gapY}px ${gapX}px`,
          position: "relative",
          marginBottom: height * 0.1,
        }}
      >
        {displayItems.map((item, index) => {
          // Intro animation (staggered pop-in)
          const introScale = spring({
            frame: frame - index * 4,
            fps,
            config: { damping: 12, stiffness: 100 },
          });

          // Active state timing
          const startFrame = introDuration + index * framesPerItem;
          const endFrame = startFrame + framesPerItem;
          
          // Custom interpolation function to guarantee monotonicity and handle any duration
          const getActiveProgress = () => {
            const transitionDuration = Math.min(10, framesPerItem * 0.2);
            if (frame < startFrame) return 0;
            if (frame > endFrame) return 0;
            if (frame < startFrame + transitionDuration) {
              return interpolate(
                frame,
                [startFrame, startFrame + transitionDuration],
                [0, 1],
                { easing: Easing.out(Easing.quad) }
              );
            }
            if (frame > endFrame - transitionDuration) {
              return interpolate(
                frame,
                [endFrame - transitionDuration, endFrame],
                [1, 0],
                { easing: Easing.in(Easing.quad) }
              );
            }
            return 1;
          };

          const activeProgress = getActiveProgress();

          // Smoothly transition scale and colors based on activeProgress
          const scale = introScale * (1 + activeProgress * 0.25); // Scale up to 1.25x when active
          const zIndex = Math.round(activeProgress * 10) + (10 - index); // Ensure active is on top
          
          const currentColor = interpolateColor(
            activeProgress,
            inactiveCardColor,
            activeGradientStart // Using start color for solid approximation in inactive state if needed
          );

          const currentTextColor = interpolateColor(
            activeProgress,
            inactiveTextColor,
            activeTextColor
          );
          
          const shadowOpacity = activeProgress * 0.6;
          
          // Text sizing
          const fontSize = cardSize * 0.55;

          return (
            <div
              key={index}
              style={{
                width: cardSize,
                height: cardSize,
                borderRadius: borderRadius,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: `scale(${scale})`,
                zIndex,
                boxShadow: `0px ${20 * activeProgress}px ${40 * activeProgress}px rgba(0,0,0,${shadowOpacity})`,
                background: activeProgress > 0 
                  ? `linear-gradient(135deg, ${activeGradientStart}, ${activeGradientEnd})` 
                  : inactiveCardColor,
                // Simulate a subtle inner highlight when inactive to match reference
                border: activeProgress === 0 ? `1px solid rgba(255,255,255,0.05)` : 'none',
              }}
            >
              <span
                style={{
                  color: currentTextColor,
                  fontSize: fontSize,
                  fontWeight: 900,
                  lineHeight: 1,
                  // When active, add a subtle text shadow
                  textShadow: activeProgress > 0.5 ? '0px 2px 10px rgba(0,0,0,0.3)' : 'none',
                  transition: "none",
                }}
              >
                {item.number}
              </span>
            </div>
          );
        })}
      </div>

      {/* Messages Container */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.15,
          width: "100%",
          height: height * 0.15,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {displayItems.map((item, index) => {
          const startFrame = introDuration + index * framesPerItem;
          const endFrame = startFrame + framesPerItem;
          
          const getMessageProgress = () => {
             const transitionDuration = Math.min(12, framesPerItem * 0.25);
             if (frame < startFrame) return 0;
             if (frame > endFrame) return 0;
             if (frame < startFrame + transitionDuration) {
               return interpolate(
                 frame,
                 [startFrame, startFrame + transitionDuration],
                 [0, 1],
                 { easing: Easing.out(Easing.cubic) }
               );
             }
             if (frame > endFrame - transitionDuration) {
               return interpolate(
                 frame,
                 [endFrame - transitionDuration, endFrame],
                 [1, 0],
                 { easing: Easing.in(Easing.cubic) }
               );
             }
             return 1;
          };

          const msgProgress = getMessageProgress();
          const translateY = (1 - msgProgress) * 20;

          if (msgProgress === 0) return null;

          return (
            <div
              key={`msg-${index}`}
              style={{
                position: "absolute",
                opacity: msgProgress,
                transform: `translateY(${translateY}px)`,
                textAlign: "center",
                width: width * 0.6,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "10px",
              }}
            >
              <div 
                style={{
                  color: activeGradientStart,
                  fontSize: pointFontSize,
                  fontWeight: 700,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase"
                }}
              >
                Point {item.number}
              </div>
              <div
                style={{
                  color: activeTextColor,
                  fontSize: messageFontSize,
                  fontWeight: 400,
                  lineHeight: 1.3,
                }}
              >
                {item.message}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// Helper to interpolate hex colors safely without extra libraries
function interpolateColor(progress: number, color1: string, color2: string) {
  const hex1 = color1.replace("#", "");
  const hex2 = color2.replace("#", "");
  
  const r1 = parseInt(hex1.substring(0, 2), 16);
  const g1 = parseInt(hex1.substring(2, 4), 16);
  const b1 = parseInt(hex1.substring(4, 6), 16);
  
  const r2 = parseInt(hex2.substring(0, 2), 16);
  const g2 = parseInt(hex2.substring(2, 4), 16);
  const b2 = parseInt(hex2.substring(4, 6), 16);
  
  const r = Math.round(r1 + (r2 - r1) * progress);
  const g = Math.round(g1 + (g2 - g1) * progress);
  const b = Math.round(b1 + (b2 - b1) * progress);
  
  return `rgb(${r}, ${g}, ${b})`;
}

export default SequenceHighlight;